source='''def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]
    marker = next(( (r, c - 8) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5), None)
    if marker is None:
        raise ValueError("missing marker")
    r, c = marker
    out[r][c] = 5

    motifs = []
    # The motifs are read down the left column, then down the right column.
    for c0 in (0, 4):
        for r0 in range(0, h - 2, 4):
            cells = [grid[rr][cc] for rr in range(r0, r0 + 3) for cc in range(c0, c0 + 3)]
            nonzero = {v for v in cells if v}
            if not nonzero:
                continue
            color = next(iter(nonzero))
            sig = tuple(
                tuple(1 if grid[rr][cc] == color else 0 for cc in range(c0, c0 + 3))
                for rr in range(r0, r0 + 3)
            )
            if sig == ((1, 1, 0), (1, 0, 1), (0, 1, 0)):
                direction, length = "R", 3
            elif sig == ((1, 0, 1), (1, 0, 1), (1, 1, 1)):
                direction, length = "L", 2
            elif sig == ((1, 0, 1), (0, 1, 0), (0, 1, 0)):
                direction, length = "D", 2
            elif sig == ((1, 1, 1), (0, 1, 0), (1, 0, 1)):
                direction, length = "L", 4
            else:
                raise ValueError((r0, c0, color, sig))
            motifs.append((direction, length, color))

    for direction, length, color in motifs:
        r += 1
        for i in range(length):
            cc = c + i if direction == "R" else c - i if direction == "L" else c
            rr = r + i if direction == "D" else r
            if 0 <= rr < h and 0 <= cc < 7:
                out[rr][cc] = color
        if direction == "D":
            r += length - 1
        else:
            c += (length - 1) * (1 if direction == "R" else -1)
    return out
'''
